#pragma once
#include <algorithm>
#include <cstdint>
#include <memory>
#include <string>
#include <unordered_map>
#include <vector>
namespace engine::scripting {
enum class PinType{Bool,Int,Float,String,Vec2,Vec3,Vec4,Entity,Asset,Event,Any};
struct PinValue{PinType type{PinType::Any};bool boolVal{false};int intVal{0};float floatVal{0};std::string stringVal;std::uint64_t entityHandle{0},assetHandle{0};bool is_compatible(PinType e)const{return e==PinType::Any||type==PinType::Any||type==e;}};
struct PinDef{std::string name;PinType type{PinType::Any};bool required{true};PinValue defaultValue;};
struct NodeDef{std::string type_name;std::string category;std::string description;std::vector<PinDef> inputs,outputs;std::string reflection_type;};
struct NodeInstance{std::uint64_t id{0};std::string type_name;std::unordered_map<std::string,PinValue> inputValues,outputValues;};
struct Edge{std::uint64_t fromNodeId{0};std::string fromPin;std::uint64_t toNodeId{0};std::string toPin;};
struct GraphValidation{std::vector<std::string> errors;bool valid()const noexcept{return errors.empty();}};
class IVisualScriptGraph{public:virtual~IVisualScriptGraph()=default;virtual std::uint64_t add_node(const NodeInstance&)=0;virtual bool remove_node(std::uint64_t)=0;virtual const NodeInstance*get_node(std::uint64_t)const=0;virtual std::vector<std::uint64_t>node_ids()const=0;virtual bool add_edge(const Edge&,std::string* error=nullptr)=0;virtual bool remove_edge(std::uint64_t,const std::string&,std::uint64_t,const std::string&)=0;virtual const std::vector<Edge>&edges()const=0;virtual GraphValidation validate()const=0;virtual std::vector<std::uint64_t>topological_order()const=0;virtual bool register_node_type(const NodeDef&,std::string* error=nullptr)=0;virtual const NodeDef*get_node_type(const std::string&)const=0;virtual std::vector<std::string>node_type_names()const=0;virtual std::string to_json()const=0;virtual bool load_json(const std::string&,std::string&)=0;};
class VisualScriptGraph final:public IVisualScriptGraph{std::uint64_t nextId_{1};std::unordered_map<std::uint64_t,NodeInstance>nodes_;std::vector<Edge>edges_;std::unordered_map<std::string,NodeDef>types_;public:std::uint64_t add_node(const NodeInstance&n)override{auto x=n;x.id=nextId_++;nodes_[x.id]=x;return x.id;}bool remove_node(std::uint64_t id)override{if(!nodes_.erase(id))return false;edges_.erase(std::remove_if(edges_.begin(),edges_.end(),[&](const auto&e){return e.fromNodeId==id||e.toNodeId==id;}),edges_.end());return true;}const NodeInstance*get_node(std::uint64_t id)const override{auto i=nodes_.find(id);return i==nodes_.end()?nullptr:&i->second;}std::vector<std::uint64_t>node_ids()const override{std::vector<std::uint64_t>o;for(const auto&[id,_]:nodes_)o.push_back(id);std::sort(o.begin(),o.end());return o;}bool add_edge(const Edge&e,std::string*err=nullptr)override{auto*f=get_node(e.fromNodeId);auto*t=get_node(e.toNodeId);if(!f||!t){if(err)*err="from node not found";return false;}if(e.fromPin.empty()||e.toPin.empty()){if(err)*err="pin_required";return false;}auto fi=types_.find(f->type_name),ti=types_.find(t->type_name);if(fi==types_.end()||ti==types_.end()){if(err)*err="node_type_not_found";return false;}auto fo=std::find_if(fi->second.outputs.begin(),fi->second.outputs.end(),[&](const auto&p){return p.name==e.fromPin;});auto in=std::find_if(ti->second.inputs.begin(),ti->second.inputs.end(),[&](const auto&p){return p.name==e.toPin;});if(fo==fi->second.outputs.end()||in==ti->second.inputs.end()){if(err)*err="pin_not_found";return false;}if(fo->type!=PinType::Any&&in->type!=PinType::Any&&fo->type!=in->type){if(err)*err="type mismatch";return false;}for(const auto&x:edges_)if(x.toNodeId==e.toNodeId&&x.toPin==e.toPin){if(err)*err="input already connected";return false;}edges_.push_back(e);return true;}bool remove_edge(std::uint64_t a,const std::string&b,std::uint64_t c,const std::string&d)override{auto i=std::find_if(edges_.begin(),edges_.end(),[&](const auto&e){return e.fromNodeId==a&&e.fromPin==b&&e.toNodeId==c&&e.toPin==d;});if(i==edges_.end())return false;edges_.erase(i);return true;}const std::vector<Edge>&edges()const override{return edges_;}GraphValidation validate()const override{GraphValidation r;for(const auto&[id,n]:nodes_){auto d=types_.find(n.type_name);if(d==types_.end()){r.errors.push_back("unknown_node_type:"+n.type_name);continue;}for(const auto&p:d->second.inputs)if(p.required&&!n.inputValues.count(p.name)&&std::none_of(edges_.begin(),edges_.end(),[&](const auto&e){return e.toNodeId==id&&e.toPin==p.name;}))r.errors.push_back("required_input_missing:"+std::to_string(id)+":"+p.name);}if(nodes_.size()&&topological_order().empty())r.errors.push_back("cycle_detected");return r;}std::vector<std::uint64_t>topological_order()const override{std::unordered_map<std::uint64_t,int>d;for(const auto&[id,_]:nodes_)d[id]=0;for(const auto&e:edges_)if(d.count(e.toNodeId))++d[e.toNodeId];std::vector<std::uint64_t>q;for(const auto&[id,n]:d)if(!n)q.push_back(id);std::sort(q.begin(),q.end());for(size_t i=0;i<q.size();++i)for(const auto&e:edges_)if(e.fromNodeId==q[i]&&!--d[e.toNodeId])q.push_back(e.toNodeId);return q.size()==nodes_.size()?q:std::vector<std::uint64_t>{};}bool register_node_type(const NodeDef&d,std::string*e=nullptr)override{if(d.type_name.empty()){if(e)*e="type_required";return false;}if(types_.count(d.type_name)){if(e)*e="duplicate_type";return false;}types_[d.type_name]=d;return true;}const NodeDef*get_node_type(const std::string&n)const override{auto i=types_.find(n);return i==types_.end()?nullptr:&i->second;}std::vector<std::string>node_type_names()const override{std::vector<std::string>o;for(const auto&[n,_]:types_)o.push_back(n);std::sort(o.begin(),o.end());return o;}std::string to_json()const override{return "{\"version\":1,\"nodes\":"+std::to_string(nodes_.size())+",\"edges\":"+std::to_string(edges_.size())+"}";}bool load_json(const std::string&j,std::string&e)override{if(j.find("\"version\":1")==std::string::npos){e="unsupported_graph_version";return false;}return true;}};
}
